-- ============================================================================
-- Migration 1101: the Powder Metal machines -- the crews memory gives them, and India
-- ============================================================================
-- Generated by scripts/generate-powder-metal-machines-migration.js; re-run it and diff instead of editing.
--
-- Powder Metal had its 16 machines in HR Rates for the USA only, so a Powder Metal part in India was not costed ("HR Rates has no powder
-- metal machines for India"), and their crews were wrong:
--   * crews: memory gives the smaller presses half an operator and the 36" belt furnace one and a half; they were stored as 1 and 2 (rounded
--     up when the column held whole numbers; migration 971 widened it), so their labour was charged up to twice over. Set from
--     memory/Powder metal/Machines, before the India twins copy them.
--
-- India: memory/Countries data/India_XML_Data_.csv, commodity "Powder Metal" (16 machines, the same as the USA files): each machine's direct and indirect
-- overhead (USD/hr, to cents) on its USA twin (same class, exact name). Labour: the India rate of the processes' wage grade
-- (memory/Powder metal/wage_grade_associations.csv: 4 - Metal), the rate the India rows of that grade carry in HR Rates, 2.30 USD/hr.
--   Compaction Pressing     13 machine(s)
--   Furnace Sintering       3 machine(s)
--
-- Idempotent. Verify:
--   SELECT location, machine_class, count(*), sum(operators) FROM mhr_records WHERE process_group = 'Powder Metal' GROUP BY 1, 2 ORDER BY 1, 2;
-- ============================================================================

UPDATE mhr_records m
SET operators = v.operators, updated_at = now()
FROM (VALUES
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 15 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 12 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 30 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 35 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 60 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 100 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 150 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 200 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 160 ton$str$, 0.5::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 600 ton$str$, 1::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre MM - 750 ton$str$, 1::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 650 ton$str$, 1::numeric),
  ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 1600 ton$str$, 1::numeric),
  ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 12" Belt$str$, 1::numeric),
  ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 24" Belt$str$, 1::numeric),
  ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 36" Belt$str$, 1.5::numeric)
) AS v(machine_class, machine_name, operators)
WHERE m.process_group = $str$Powder Metal$str$ AND m.location = 'USA' AND m.machine_class = v.machine_class AND m.machine_name = v.machine_name
  AND m.operators IS DISTINCT FROM v.operators;

DO $powder_metal_machines$
DECLARE
  cols text; sel text; r record; src_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '$5'
        WHEN 'country_code'                            THEN '$6'
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN '$7'
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'src.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  -- (location, country, machine class, machine name, labour, direct overhead, indirect overhead, source key), USD/hr
  FOR r IN SELECT * FROM (VALUES
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 100 ton$str$, 2.3, 12.93, 1.04, $str$Compaction Pressing:Gasbarre DSP - 100 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 15 ton$str$, 2.3, 6.5, 0.95, $str$Compaction Pressing:Gasbarre DSP - 15 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 150 ton$str$, 2.3, 18.67, 1.06, $str$Compaction Pressing:Gasbarre DSP - 150 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 200 ton$str$, 2.3, 22.29, 1.22, $str$Compaction Pressing:Gasbarre DSP - 200 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 30 ton$str$, 2.3, 9.21, 1.04, $str$Compaction Pressing:Gasbarre DSP - 30 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 60 ton$str$, 2.3, 10.94, 1.12, $str$Compaction Pressing:Gasbarre DSP - 60 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 600 ton$str$, 2.3, 55.21, 1.49, $str$Compaction Pressing:Gasbarre DSP - 600 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Gasbarre MM - 750 ton$str$, 2.3, 60.73, 1.58, $str$Compaction Pressing:Gasbarre MM - 750 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 12 ton$str$, 2.3, 7.06, 1.25, $str$Compaction Pressing:Generic Hydraulic - 12 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 160 ton$str$, 2.3, 24.98, 1.42, $str$Compaction Pressing:Generic Hydraulic - 160 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 1600 ton$str$, 2.3, 94.84, 1.45, $str$Compaction Pressing:Generic Hydraulic - 1600 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 35 ton$str$, 2.3, 11.11, 1.32, $str$Compaction Pressing:Generic Hydraulic - 35 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 650 ton$str$, 2.3, 66.63, 1.49, $str$Compaction Pressing:Generic Hydraulic - 650 ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_furnace_sintering$str$, $str$Abbott - 12" Belt$str$, 2.3, 17.39, 3, $str$Furnace Sintering:Abbott - 12" Belt:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_furnace_sintering$str$, $str$Abbott - 24" Belt$str$, 2.3, 34.79, 3.9, $str$Furnace Sintering:Abbott - 24" Belt:India$str$),
    ($str$India$str$, $str$IN$str$, $str$powder_metal_furnace_sintering$str$, $str$Abbott - 36" Belt$str$, 2.3, 52.18, 5.44, $str$Furnace Sintering:Abbott - 36" Belt:India$str$)
  ) AS v(location, country, machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO src_id FROM mhr_records
    WHERE process_group = $str$Powder Metal$str$ AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF src_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = r.location AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records src WHERE src.id = $1', cols, sel)
      USING src_id, r.direct, r.indirect, r.labor, r.location, r.country, r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE '% twins inserted: %', $str$Powder Metal$str$, n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE '% twins with no USA row (not inserted): %', $str$Powder Metal$str$, missing;
  END IF;
END $powder_metal_machines$;

DO $powder_metal_check$
DECLARE wrong text[]; n integer;
BEGIN
  SELECT array_agg(m.location || ': ' || m.machine_name || ' ' || m.operators ORDER BY m.location, m.machine_name) INTO wrong
  FROM mhr_records m JOIN (VALUES
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 15 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 12 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 30 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 35 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 60 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 100 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 150 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 200 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 160 ton$str$, 0.5::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre DSP - 600 ton$str$, 1::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Gasbarre MM - 750 ton$str$, 1::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 650 ton$str$, 1::numeric),
    ($str$powder_metal_compaction_pressing$str$, $str$Generic Hydraulic - 1600 ton$str$, 1::numeric),
    ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 12" Belt$str$, 1::numeric),
    ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 24" Belt$str$, 1::numeric),
    ($str$powder_metal_furnace_sintering$str$, $str$Abbott - 36" Belt$str$, 1.5::numeric)
  ) AS v(machine_class, machine_name, operators) ON m.machine_class = v.machine_class AND m.machine_name = v.machine_name
  WHERE m.process_group = $str$Powder Metal$str$ AND m.location IN ('USA', 'India') AND m.operators IS DISTINCT FROM v.operators;
  IF wrong IS NOT NULL THEN RAISE EXCEPTION 'Powder Metal machines whose crew is not memory''s: %', wrong; END IF;
  SELECT count(*) INTO n FROM mhr_records WHERE process_group = $str$Powder Metal$str$ AND location = 'India' AND machine_class IN ($str$powder_metal_compaction_pressing$str$, $str$powder_metal_furnace_sintering$str$);
  IF n <> 16 THEN RAISE EXCEPTION 'expected 16 India Powder Metal machines, found %', n; END IF;
END $powder_metal_check$;

NOTIFY pgrst, 'reload schema';
